pt.statement:
O que o programa em C a seguir imprime em um sistema UNIX, supondo que fork tenha sucesso?

int x = 5;
int main(void) {
	pid_t pid = fork();
	if (pid == 0) { x = 10; exit(0); }
	waitpid(pid, NULL, 0);
	printf("%d\n", x);
	return 0;
}

example.content:
#include <stdio.h>
#include <stdlib.h>
#include <sys/wait.h>
#include <unistd.h>

int x = 5;

int main(void) {
	pid_t pid = fork();
	if (pid == 0) {
		x = 10;
		exit(0);
	}
	waitpid(pid, NULL, 0);
	printf("%d\n", x);
	return 0;
}

